use crate::{DslValue,NativeDecodeControl,NativeReceive,NativeReceiver,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone::{RetainedCloneSource,RetainedCloneClose}};
#[test]fn actual_fixed_array_receiving_has_no_per_element_birth_or_take_callback(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();
 fn case<const N:usize>(f:&serde_json::Value,values:Vec<bool>,cut:Option<u64>){let s=&f["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();fn post(g:&mut RetainedCloneGrant,f:&mut u64,p:RetainedCloneProgress,w:u64){assert!(p.fits(*g));g.maximum_items-=p.copied_items;g.maximum_copy_bytes-=p.copied_bytes;g.maximum_capacity_bytes-=p.retained_capacity_bytes;g.maximum_release_bytes-=p.released_bytes;*f=f.checked_sub(w).unwrap();}fn offer(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:g.maximum_items.min(1),..g}}
 let(turn,heap)=crate::observe_retirement_allocations(||<[bool;N]as NativeReceive<DslValue>>::receiver());assert_eq!(heap,(0,0));let mut receiver=turn;let mut source={let mut wallet=(&mut bank,&mut fuel);crate::source_fixture::capture(DslValue::Array(values.iter().copied().map(DslValue::Bool).collect()),&mut wallet,|w|RetainedCloneGrant{maximum_items:w.0.maximum_items.min(1),..*w.0},|w|*w.1,|w,p,work,_,_|post(w.0,w.1,p,work))};let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.maximum_capacity_bytes,&mut callback);let mut output=None;
 for turn_index in 0..s["maximumTurns"].as_u64().unwrap(){if cut.is_some_and(|cut|turn_index==cut){break}if receiver.output_ready(){let(turn,heap)=crate::observe_retirement_allocations(||receiver.take(RetainedCloneGrant{maximum_items:0,..bank}));assert!(turn.result.unwrap().is_none());assert_eq!(turn.work,0);assert_eq!(heap,(0,0));let(turn,heap)=crate::observe_retirement_allocations(||receiver.take(RetainedCloneGrant{maximum_copy_bytes:0,..offer(bank)}));assert_eq!(turn.work,1);assert_eq!(heap,(0,0));let(value,p)=turn.result.unwrap().unwrap();assert_eq!(p.copied_bytes,0);post(&mut bank,&mut fuel,p,turn.work);output=Some(value);break}let d=receiver.demands(source.borrow(),4096,fuel).unwrap();let g=offer(bank);assert!(crate::retained_clone::retained_clone_grant_admits(g,d));for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let(turn,heap)=crate::observe_retirement_allocations(||{let maximum=fuel;let grant=denied;crate::source_fixture::receive(&mut control,grant,crate::source_fixture::WorkLoan::new(&maximum,maximum),|control|{let maximum=control.available_work_units().unwrap();receiver.advance(source.borrow(),control,4096,maximum,grant)})});assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(receiver.demands(source.borrow(),4096,fuel).unwrap(),d);}let turn={let maximum=fuel;let grant=g;crate::source_fixture::receive(&mut control,grant,crate::source_fixture::WorkLoan::new(&maximum,maximum),|control|{let maximum=control.available_work_units().unwrap();receiver.advance(source.borrow(),control,4096,maximum,grant)})};let work=turn.work;post(&mut bank,&mut fuel,turn.result.unwrap().progress(),work);}
 if cut.is_none(){let value=output.as_ref().unwrap();assert_eq!(serde_json::to_value(value.as_slice()).unwrap(),serde_json::to_value(&values).unwrap());assert!(s["fuel"].as_u64().unwrap()-fuel>=N as u64);}let mut owned=output;let mut close=RetainedCloneClose::default();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if owned.is_none()&&close.is_empty(){break}let turn=if close.is_empty(){let t=close.begin_granted(&mut owned,offer(bank));crate::RetainedWorkOutcome{result:t.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))),work:t.work}}else{close.step_granted(offer(bank))};let work=turn.work;post(&mut bank,&mut fuel,turn.result.unwrap().progress(),work);}assert!(owned.is_none()&&close.is_empty());receiver.begin_close();let mut actual=None;for _ in 0..s["maximumTurns"].as_u64().unwrap(){if receiver.terminal_is_empty()&&actual.is_none(){break}let turn=crate::source_fixture::close_step(&mut actual,offer(bank),fuel,receiver.close_demands(4096),receiver.close_work_demand(4096),|g,a|receiver.close_step(g,a));let work=turn.work;let step=turn.result.unwrap();if matches!(step,RetainedCloneStep::Complete(_)){assert!(receiver.terminal_is_empty());}post(&mut bank,&mut fuel,step.progress(),work);}assert!(receiver.terminal_is_empty());drop(receiver);for _ in 0..s["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty()&&actual.is_none(){break}let turn=crate::source_fixture::close_step(&mut actual,offer(bank),fuel,source.next_close_demand(4096),source.next_close_work_demand(4096),|g,a|source.close_step(g,a));let work=turn.work;post(&mut bank,&mut fuel,turn.result.unwrap().progress(),work);}assert!(source.terminal_is_empty());}
 case::<0>(&f,vec![],None);case::<3>(&f,serde_json::from_value(f["cases"][1]["values"].clone()).unwrap(),None);case::<4097>(&f,vec![true;4097],None);for cut in f["cancelCuts"].as_array().unwrap(){case::<3>(&f,vec![true,false,true],Some(cut.as_u64().unwrap()));}
}
